  assert rc==1,(sql,rc)
  L.sqlite3_errmsg.argtypes=[P];L.sqlite3_errmsg.restype=C.c_char_p
  print(json.dumps({'sourceId':source,'sql':sql,'error':L.sqlite3_errmsg(db).decode(),'code':rc}))
